@page "/categories"
@page "/categories/{CategoryName}"
@using RecipeCommunity.Services
@using RecipeCommunity.Models

<PageTitle>@(CategoryName is not null ? $"{CategoryName} Recipes" : "All Categories")</PageTitle>

@if (CategoryName is null)
{
    <h1>📂 All Categories</h1>
    <div class="list-group mt-3">
        @foreach (var cat in Categories)
        {
            <a href="categories/@cat" class="list-group-item list-group-item-action d-flex justify-content-between align-items-center">
                @cat
                <span class="badge bg-primary rounded-pill">@RecipeService.GetByCategory(cat).Count</span>
            </a>
        }
    </div>
}
else
{
    <h1>@CategoryName Recipes</h1>
    <a href="categories" class="btn btn-sm btn-outline-secondary mb-3">← All Categories</a>

    @if (!Recipes.Any())
    {
        <div class="alert alert-info">No recipes found in this category.</div>
    }
    else
    {
        <div class="row row-cols-1 row-cols-md-2 g-4">
            @foreach (var recipe in Recipes)
            {
                <div class="col">
                    <div class="card h-100 shadow-sm">
                        <div class="card-body">
                            <h5 class="card-title">@recipe.Title</h5>
                            <p class="card-text">@recipe.Description</p>
                            <div class="text-warning mb-2">
                                @for (int i = 1; i <= 5; i++)
                                {
                                    <span>@(i <= (int)Math.Round(recipe.AverageRating) ? "★" : "☆")</span>
                                }
                                <small class="text-muted ms-1">(@recipe.TotalRatings ratings)</small>
                            </div>
                            <a href="recipe/@recipe.Id" class="btn btn-primary btn-sm">View Recipe</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
}

@code {
    [Parameter] public string? CategoryName { get; set; }
    [Inject] public RecipeService RecipeService { get; set; } = default!;

    private List<string> Categories = [];
    private List<Recipe> Recipes = [];

    protected override void OnParametersSet()
    {
        Categories = RecipeService.GetCategories();
        Recipes = CategoryName is not null ? RecipeService.GetByCategory(CategoryName) : [];
    }
}

@page "/recipe/{Id:int}"
@using RecipeCommunity.Services
@using RecipeCommunity.Models

<PageTitle>@(Recipe?.Title ?? "Recipe Not Found")</PageTitle>

@if (Recipe is null)
{
    <div class="alert alert-warning">Recipe not found.</div>
    <a href="categories" class="btn btn-outline-secondary">← Browse Recipes</a>
}
else
{
    <a href="categories/@Recipe.Category" class="btn btn-sm btn-outline-secondary mb-3">← Back to @Recipe.Category</a>

    <h1>@Recipe.Title</h1>
    <span class="badge bg-secondary mb-3">@Recipe.Category</span>
    <p class="lead">@Recipe.Description</p>

    <div class="row mt-4">
        <div class="col-md-4">
            <div class="card">
                <div class="card-header"><strong>🧾 Ingredients</strong></div>
                <ul class="list-group list-group-flush">
                    @foreach (var ingredient in Recipe.Ingredients)
                    {
                        <li class="list-group-item">@ingredient</li>
                    }
                </ul>
            </div>
        </div>

        <div class="col-md-8">
            <div class="card">
                <div class="card-header"><strong>👩‍🍳 Steps</strong></div>
                <div class="card-body">
                    <ol>
                        @foreach (var step in Recipe.Steps)
                        {
                            <li class="mb-2">@step</li>
                        }
                    </ol>
                </div>
            </div>
        </div>
    </div>

    <div class="card mt-4">
        <div class="card-body">
            <h5>⭐ Rate This Recipe</h5>
            <p class="text-muted">
                Average: @Recipe.AverageRating.ToString("F1") / 5
                (@Recipe.TotalRatings ratings)
            </p>
            <StarRating RecipeId="Recipe.Id" />
        </div>
    </div>
}

@code {
    [Parameter] public int Id { get; set; }
    [Inject] public RecipeService RecipeService { get; set; } = default!;

    private Recipe? Recipe;

    protected override void OnParametersSet()
    {
        Recipe = RecipeService.GetById(Id);
    }
}

@rendermode InteractiveServer
@using RecipeCommunity.Services

<div class="d-inline-flex align-items-center">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <button class="btn btn-link p-0 fs-3 text-decoration-none"
                style="color: @(star <= (Submitted ? SubmittedRating : HoverRating) ? "#ffc107" : "#dee2e6"); cursor: pointer;"
                @onmouseover="() => OnHover(star)"
                @onmouseout="OnHoverOut"
                @onclick="() => SubmitRating(star)"
                disabled="@Submitted">
            ★
        </button>
    }

    @if (Submitted)
    {
        <span class="ms-2 text-success fw-bold">✓ Thanks! You rated @SubmittedRating/5</span>
    }
    else
    {
        <span class="ms-2 text-muted">Click a star to rate</span>
    }
</div>

@code {
    [Parameter, EditorRequired] public int RecipeId { get; set; }
    [Inject] public RecipeService RecipeService { get; set; } = default!;

    private int HoverRating;
    private int SubmittedRating;
    private bool Submitted;

    private void OnHover(int star) { if (!Submitted) HoverRating = star; }
    private void OnHoverOut() { if (!Submitted) HoverRating = 0; }

    private void SubmitRating(int star)
    {
        if (Submitted) return;
        RecipeService.AddRating(RecipeId, star);
        SubmittedRating = star;
        Submitted = true;
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeCommunity.Services
@using RecipeCommunity.Models

<PageTitle>Submit a Recipe</PageTitle>

<h1>📝 Submit Your Recipe</h1>
<p class="text-muted">Share your favorite recipe with the community.</p>

@if (SubmittedSuccessfully)
{
    <div class="alert alert-success">
        <h4>🎉 Recipe submitted!</h4>
        <p>Your recipe "<strong>@Submission.Title</strong>" has been added.</p>
        <a href="categories/@Submission.Category" class="btn btn-primary btn-sm">View in @Submission.Category</a>
        <button class="btn btn-outline-secondary btn-sm ms-2" @onclick="Reset">Submit Another</button>
    </div>
}
else
{
    <EditForm Model="Submission" OnValidSubmit="HandleSubmit" FormName="recipeForm">
        <DataAnnotationsValidator />

        <div class="mb-3">
            <label class="form-label fw-bold">Recipe Title</label>
            <InputText @bind-Value="Submission.Title" class="form-control" placeholder="e.g. Grandma's Apple Pie" />
        </div>

        <div class="mb-3">
            <label class="form-label fw-bold">Category</label>
            <InputSelect @bind-Value="Submission.Category" class="form-select">
                <option value="">-- Select a category --</option>
                @foreach (var cat in Categories)
                {
                    <option value="@cat">@cat</option>
                }
                <option value="Other">Other</option>
            </InputSelect>
        </div>

        <div class="mb-3">
            <label class="form-label fw-bold">Ingredients</label>
            <InputTextArea @bind-Value="Submission.Ingredients" class="form-control" rows="5"
                           placeholder="One ingredient per line&#10;e.g.&#10;2 cups flour&#10;1 cup sugar&#10;3 eggs" />
            <div class="form-text">Enter one ingredient per line.</div>
        </div>

        <div class="mb-3">
            <label class="form-label fw-bold">Steps</label>
            <InputTextArea @bind-Value="Submission.Steps" class="form-control" rows="5"
                           placeholder="One step per line&#10;e.g.&#10;Preheat oven to 350°F&#10;Mix dry ingredients&#10;Add wet ingredients" />
            <div class="form-text">Enter one step per line.</div>
        </div>

        <button type="submit" class="btn btn-success"
                disabled="@(string.IsNullOrWhiteSpace(Submission.Title) || string.IsNullOrWhiteSpace(Submission.Category) || string.IsNullOrWhiteSpace(Submission.Ingredients) || string.IsNullOrWhiteSpace(Submission.Steps))">
            🚀 Submit Recipe
        </button>
    </EditForm>
}

@code {
    [Inject] public RecipeService RecipeService { get; set; } = default!;

    private RecipeSubmission Submission = new();
    private List<string> Categories = [];
    private bool SubmittedSuccessfully;

    protected override void OnInitialized()
    {
        Categories = RecipeService.GetCategories();
    }

    private void HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(Submission.Title) || string.IsNullOrWhiteSpace(Submission.Category)
            || string.IsNullOrWhiteSpace(Submission.Ingredients) || string.IsNullOrWhiteSpace(Submission.Steps))
            return;

        RecipeService.AddRecipe(Submission);
        SubmittedSuccessfully = true;
    }

    private void Reset()
    {
        Submission = new();
        SubmittedSuccessfully = false;
    }
}

