@page "/"
@using RecipeCommunity.Services

<PageTitle>Recipe Community</PageTitle>

<h1>🍽️ Welcome to Recipe Community</h1>
<p class="lead">Discover, share, and rate delicious recipes from around the world.</p>

<hr />

<h2>Browse by Category</h2>
<div class="row row-cols-1 row-cols-md-3 g-4 mt-2">
    @foreach (var category in Categories)
    {
        <div class="col">
            <div class="card h-100 shadow-sm">
                <div class="card-body text-center">
                    <h3 class="card-title">@GetEmoji(category) @category</h3>
                    <p class="card-text text-muted">@GetRecipeCount(category) recipes</p>
                    <a href="categories/@category" class="btn btn-outline-primary">View Recipes</a>
                </div>
            </div>
        </div>
    }
</div>

<hr class="mt-5" />

<div class="text-center mt-4">
    <h4>Have a recipe to share?</h4>
    <a href="submit" class="btn btn-success btn-lg mt-2">📝 Submit Your Recipe</a>
</div>

@code {
    [Inject] public RecipeService RecipeService { get; set; } = default!;

    private List<string> Categories = [];

    protected override void OnInitialized()
    {
        Categories = RecipeService.GetCategories();
    }

    private int GetRecipeCount(string category) => RecipeService.GetByCategory(category).Count;

    private string GetEmoji(string category) => category switch
    {
        "Italian" => "🍝",
        "Indian" => "🍛",
        "Asian" => "🥢",
        "Mexican" => "🌮",
        "Desserts" => "🍰",
        "Salads" => "🥗",
        _ => "🍴"
    };
}

toolArgs.file_text:
@page "/recipe/{Id:int}"
@using RecipeCommunity.Services
@using RecipeCommunity.Models

<PageTitle>@(Recipe?.Title ?? "Recipe Not Found")</PageTitle>

@if (Recipe is null)
{
    <div class="alert alert-warning">Recipe not found.</div>
    <a href="categories" class="btn btn-outline-secondary">← Browse Recipes</a>
}
else
{
    <a href="categories/@Recipe.Category" class="btn btn-sm btn-outline-secondary mb-3">← Back to @Recipe.Category</a>

    <h1>@Recipe.Title</h1>
    <span class="badge bg-secondary mb-3">@Recipe.Category</span>
    <p class="lead">@Recipe.Description</p>

    <div class="row mt-4">
        <div class="col-md-4">
            <div class="card">
                <div class="card-header"><strong>🧾 Ingredients</strong></div>
                <ul class="list-group list-group-flush">
                    @foreach (var ingredient in Recipe.Ingredients)
                    {
                        <li class="list-group-item">@ingredient</li>
                    }
                </ul>
            </div>
        </div>

        <div class="col-md-8">
            <div class="card">
                <div class="card-header"><strong>👩‍🍳 Steps</strong></div>
                <div class="card-body">
                    <ol>
                        @foreach (var step in Recipe.Steps)
                        {
                            <li class="mb-2">@step</li>
                        }
                    </ol>
                </div>
            </div>
        </div>
    </div>

    <div class="card mt-4">
        <div class="card-body">
            <h5>⭐ Rate This Recipe</h5>
            <p class="text-muted">
                Average: @Recipe.AverageRating.ToString("F1") / 5
                (@Recipe.TotalRatings ratings)
            </p>
            <StarRating RecipeId="Recipe.Id" />
        </div>
    </div>
}

@code {
    [Parameter] public int Id { get; set; }
    [Inject] public RecipeService RecipeService { get; set; } = default!;

    private Recipe? Recipe;

    protected override void OnParametersSet()
    {
        Recipe = RecipeService.GetById(Id);
    }
}

@rendermode InteractiveServer
@using RecipeCommunity.Services

<div class="d-inline-flex align-items-center">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <button class="btn btn-link p-0 fs-3 text-decoration-none"
                style="color: @(star <= (Submitted ? SubmittedRating : HoverRating) ? "#ffc107" : "#dee2e6"); cursor: pointer;"
                @onmouseover="() => OnHover(star)"
                @onmouseout="OnHoverOut"
                @onclick="() => SubmitRating(star)"
                disabled="@Submitted">
            ★
        </button>
    }

    @if (Submitted)
    {
        <span class="ms-2 text-success fw-bold">✓ Thanks! You rated @SubmittedRating/5</span>
    }
    else
    {
        <span class="ms-2 text-muted">Click a star to rate</span>
    }
</div>

@code {
    [Parameter, EditorRequired] public int RecipeId { get; set; }
    [Inject] public RecipeService RecipeService { get; set; } = default!;

    private int HoverRating;
    private int SubmittedRating;
    private bool Submitted;

    private void OnHover(int star) { if (!Submitted) HoverRating = star; }
    private void OnHoverOut() { if (!Submitted) HoverRating = 0; }

    private void SubmitRating(int star)
    {
        if (Submitted) return;
        RecipeService.AddRating(RecipeId, star);
        SubmittedRating = star;
        Submitted = true;
    }
}

